const CR = 1e7;               // rupees in a crore
const KL_PER_MLD_YR = 365000; // kL in 1 MLD for a year

function crf(r, n) { return r === 0 ? 1 / n : r / (1 - Math.pow(1 + r, -n)); }

function base() { const o = {}; for (const k in P) o[k] = P[k].v; return o; }

function compute(x) {
  const prod_kl = x.prod_mld * KL_PER_MLD_YR;
  const billed_kl = prod_kl * (1 - x.nrw);
  const sew_kl = x.sewage_mld * KL_PER_MLD_YR;
  const treated_kl = x.treated_mld * KL_PER_MLD_YR;

  const prod_scale = x.prod_mld / 1900;                            // electricity scales with water pumped
  const energy_cr_m = x.energy_cr_m * prod_scale;
  const opex_cr_m = (x.opex_cr_m - x.energy_cr_m + energy_cr_m) * x.opex_index;
  // Rung 0: what people pay
  const avg_revenue = x.revenue_cr_m * 12 * CR / billed_kl;
  const hh = householdBill(20, 'fy27');

  // Rung 1: today's cash cost, everything BWSSB spends, over water billed
  const opex_yr = opex_cr_m * 12 * CR;
  const cash = opex_yr / billed_kl;
  const cash_prod = opex_yr / prod_kl;
  const cash_energy = energy_cr_m * x.opex_index * 12 * CR / billed_kl;
  const delivered_kl = prod_kl * (1 - x.nrw * x.nrw_phys_share);   // billed + unbilled consumption

  // Split today's opex into water and sewerage
  const sew_opex_yr = (x.sew_share_other * (x.opex_cr_m - x.energy_cr_m) + x.sew_energy_cr_m) * x.opex_index * 12 * CR;
  const water_opex_yr = opex_yr - sew_opex_yr;
  const sew_unit_today = sew_opex_yr / treated_kl;                 // ₹ per kL sewage treated today

  // Rung 2: full financial cost (Rogers' "full supply cost" + treating sewage to standard)
  const keep = 1 - x.grant_share;
  const r = x.wacc_real;
  const cap_bulk = x.bulk_cap_mld * x.bulk_cr_mld * CR * crf(r, x.life_bulk);
  const cap_dist = x.dist_km * x.dist_cr_km * CR * crf(r, x.life_bulk);
  const cap_misc = x.misc_cr * CR * crf(r, x.life_misc);
  const cap_sewer = x.sewer_km * x.sewer_cr_km * CR * crf(r, x.life_sewer);
  const cap_stp = x.sewage_mld * x.stp_cr_mld * CR * crf(r, x.life_stp);

  const sew_per_billed = x.return_factor;                           // kL of sewage per kL billed
  const l_water_om = water_opex_yr / billed_kl;
  const l_sew_om = (sew_unit_today + x.upgrade_rs_kl) * sew_per_billed;
  const l_water_cap = keep * (cap_bulk + cap_dist + cap_misc) / billed_kl;
  const l_sew_cap = keep * (cap_sewer + cap_stp) / sew_kl * sew_per_billed;
  // Sending it back: polish all returned sewage to river quality; pipe the eastern valleys' share back over the ridge
  const ret_cap_kl = keep * x.ret_cr_mld * CR * crf(r, x.life_bulk) / KL_PER_MLD_YR;   // per kL of returned eastern sewage
  const l_polish = x.polish_rs_kl * sew_per_billed;
  const l_convey = x.return_on * x.basin_loss * sew_per_billed * (x.ret_om_rs_kl + x.ret_kwh * x.electricity_rs_kwh + ret_cap_kl);
  const l_return = l_polish + l_convey;
  const pre_reserve = l_water_om + l_sew_om + l_water_cap + l_sew_cap + l_return;
  const l_reserve = x.reserve_pct * pre_reserve;
  const financial = pre_reserve + l_reserve;

  // Rung 3: full economic cost (+ opportunity cost of the raw water + scarcity premium of the next source)
  const per_billed_from_prod = 1 / (1 - x.nrw);
  // Share of the draw lost to the Cauvery: everything except returned sewage that reaches the basin
  const ret_share = x.return_factor * (1 - x.nrw * x.nrw_phys_share);
  const lost_share = 1 - ret_share * (x.return_on ? 1 : (1 - x.basin_loss));
  const lost_share_today = 1 - ret_share * (1 - x.basin_loss);
  // Value to others: W items are lost at the intake whatever happens later; N items only for water that never returns
  // Dry-month flow: ~60% of the value is in the gorge between the intake and Sangama (lost at the intake);
  // ~40% is in the sanctuary reach below Sangama, which returned water does reach.
  const EFLOW_W = 0.6;
  const W = x.hydro_w_rs_kl + EFLOW_W * x.eflow_rs_kl + x.catchment_rs_kl;
  const Nv = x.raw_oc_rs_kl + x.hydro_n_rs_kl + x.delta_rs_kl + x.gwrech_rs_kl + (1 - EFLOW_W) * x.eflow_rs_kl;
  const l_upstream = W * per_billed_from_prod;
  const l_raw = Nv * lost_share * per_billed_from_prod;
  const l_kolar = x.return_on * x.basin_loss * sew_per_billed * x.kolar_rs_kl;
  const scarcity_prod = Math.max(0, x.lrmc_cr_mld - x.bulk_cr_mld) * CR * crf(r, x.life_bulk) / KL_PER_MLD_YR;
  const l_scarcity = scarcity_prod * per_billed_from_prod;
  const l_catchment = x.catchment_rs_kl * per_billed_from_prod;
  const l_eflow = x.eflow_rs_kl * (EFLOW_W + (1 - EFLOW_W) * lost_share) * per_billed_from_prod, l_hydro_w = x.hydro_w_rs_kl * per_billed_from_prod;
  const dry_season = W * 12 / 5;                                   // W items fall in Jan–May; priced in those months only
  const economic = financial + l_upstream + l_raw + l_kolar;
  const next_source_prod = x.lrmc_cr_mld * CR * crf(r, x.life_bulk) / KL_PER_MLD_YR;   // capital of the next source per kL produced

  // Rung 4: full social cost (+ carbon from pumping and treatment)
  const water_kwh_yr = (energy_cr_m - x.sew_energy_cr_m * prod_scale) * 12 * CR / x.electricity_rs_kwh;
  const sew_kwh_kl = x.sew_energy_cr_m * 12 * CR / x.electricity_rs_kwh / treated_kl;
  const kwh_prod = water_kwh_yr / prod_kl;
  const kwh_billed = water_kwh_yr / billed_kl + sew_kwh_kl * sew_per_billed + x.return_on * x.basin_loss * sew_per_billed * x.ret_kwh;
  const co2_kg = kwh_billed * x.grid_ef;                           // kg CO2 per kL billed (tCO2/MWh = kg/kWh)
  const l_carbon = co2_kg * (1 - x.re_share) / 1000 * x.scc_usd * x.fx;
  const l_residual = x.residual_rs_kl * sew_per_billed;
  const social = economic + l_carbon + l_residual;
  // Today's untreated sewage, valued at the NGT compensation rate, per kL billed
  const gap_mld = Math.max(0, x.sewage_mld - x.treated_mld - x.decentral_mld);
  const today_damage = gap_mld * x.ngt_cr_mld * CR / billed_kl;

  return {
    billed_mm3: billed_kl / 1e6, prod_mm3: prod_kl / 1e6, sew_mm3: sew_kl / 1e6,
    hh_bill_20: hh.total, hh_rate_20: hh.perKl, avg_revenue,
    cash, cash_prod, cash_energy, sew_unit_today,
    l_water_om, l_sew_om, l_water_cap, l_sew_cap, l_reserve, financial,
    l_raw, l_scarcity, economic, scarcity_prod,
    l_residual, gap_mld, today_damage, l_catchment, l_polish, l_convey, l_return, lost_share, lost_share_today,
    l_upstream, l_kolar, l_eflow, l_hydro_w, W_drawn: W, N_lost: Nv, dry_season,
    l_agri: x.raw_oc_rs_kl * lost_share * per_billed_from_prod, l_hydro_n: x.hydro_n_rs_kl * lost_share * per_billed_from_prod,
    l_delta: (x.delta_rs_kl + x.gwrech_rs_kl) * lost_share * per_billed_from_prod,
    kwh_billed, kwh_prod, sew_kwh_kl, co2_kg, l_carbon, social, next_source_prod,
    // per kL delivered (counts unbilled consumption) and at efficient NRW
    financial_delivered: financial * billed_kl / delivered_kl,
    financial_efficient: financial * (1 - x.nrw) / (1 - Math.min(x.nrw, x.nrw_efficient)),
    // sewerage cost not carried by water bills (borewell-derived sewage)
    sew_cost_cr: ((sew_unit_today + x.upgrade_rs_kl) * sew_kl + keep * (cap_sewer + cap_stp)) / CR,
    sew_via_bills_cr: (l_sew_om + l_sew_cap) * billed_kl / CR,
    sew_unit_full: (sew_unit_today + x.upgrade_rs_kl) + keep * (cap_sewer + cap_stp) / sew_kl,
    // regulator's view today: opex + depreciation + return on historical RAB
    regulator: (opex_yr + x.rab_hist_cr * CR * (x.reg_dep + x.reg_wacc_nom)) / billed_kl,
    revenue_req_cr: financial * billed_kl / CR,
    deficit_cr: (opex_yr - x.revenue_cr_m * 12 * CR) / CR,
    c_bulk: keep * cap_bulk / billed_kl, c_dist: keep * cap_dist / billed_kl, c_misc: keep * cap_misc / billed_kl,
    as_bulk: x.bulk_cap_mld * x.bulk_cr_mld, as_dist: x.dist_km * x.dist_cr_km,
    as_sew: x.sewer_km * x.sewer_cr_km + x.sewage_mld * x.stp_cr_mld,
    asset_cr: (x.bulk_cap_mld * x.bulk_cr_mld + x.dist_km * x.dist_cr_km + x.misc_cr + x.sewer_km * x.sewer_cr_km + x.sewage_mld * x.stp_cr_mld),
    capital_cr_yr: (cap_bulk + cap_dist + cap_misc + cap_sewer + cap_stp) / CR,
  };
}

// BWSSB domestic tariff, April 2025, with the 3% escalation on 1 Apr 2026 (fy27).
// Sanitary charge 50% of the water charge (reached end FY26), meter charge by slab.
function householdBill(kl, year) {
  const esc = year === 'fy27' ? 1.03 : 1;
  const slabs = [[8, 8.5], [25, 14], [50, 34], [Infinity, 55]];
  let water = 0, prev = 0;
  for (const [top, rate] of slabs) {
    if (kl > prev) water += (Math.min(kl, top) - prev) * rate * esc;
    prev = top;
  }
  water = Math.max(water, 68 * esc);
  const sanitary = kl <= 8 ? 14 * esc : 0.5 * water;
  const meter = kl <= 8 ? 30 : kl <= 25 ? 50 : kl <= 50 ? 75 : 150;
  const total = water + sanitary + meter;
  return { water, sanitary, meter, total, perKl: total / kl };
}

// Low/high band: move every ranged input to the end that lowers (or raises) the social cost.
function band(key) {
  const b = base(), lo = base(), hi = base();
  for (const k in P) {
    if (P[k].lo === P[k].hi) continue;
    const a = compute({ ...b, [k]: P[k].lo })[key], c = compute({ ...b, [k]: P[k].hi })[key];
    if (a <= c) { lo[k] = P[k].lo; hi[k] = P[k].hi; } else { lo[k] = P[k].hi; hi[k] = P[k].lo; }
  }
  return [compute(lo)[key], compute(hi)[key]];
}

// Monte Carlo: draw every ranged input from a triangular (low, chosen, high) distribution,
// independently, and report the 10th and 90th percentiles. Seeded so results repeat.
function triangular(u, a, c, b) {
  if (b === a) return c;
  const f = (c - a) / (b - a);
  return u < f ? a + Math.sqrt(u * (b - a) * (c - a)) : b - Math.sqrt((1 - u) * (b - a) * (b - c));
}
function percentiles(x, n = 5000, seed = 7) {
  let s = seed >>> 0;
  const rnd = () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
  const keys = ['cash', 'financial', 'economic', 'social'], out = {};
  const draws = Object.fromEntries(keys.map(k => [k, []]));
  for (let i = 0; i < n; i++) {
    const y = { ...x };
    for (const k in P) if (P[k].lo !== P[k].hi) {
      const lo = Math.min(P[k].lo, x[k]), hi = Math.max(P[k].hi, x[k]);
      y[k] = triangular(rnd(), lo, x[k], hi);
    }
    const c = compute(y);
    for (const k of keys) draws[k].push(c[k]);
  }
  for (const k of keys) { const d = draws[k].sort((a, b) => a - b); out[k] = [d[Math.floor(n * 0.1)], d[Math.floor(n * 0.9)]]; }
  return out;
}


// Project-finance view of one capex project: Cauvery Water Supply Scheme Stage VI.
// Nominal annual cash flows, priced in today's rupees per kL of bulk water delivered to city reservoirs.
// Reviewed by an independent project-finance pass; fixes: HAM sizing, sculpted lender test,
// JICA FX cost, pre-tax private equity, 40-yr life, overrun, insurance, fixed opex.

const PF = {
  capex_cr:     { v: 6939, lo: 5177, hi: 6939, unit: '₹ cr', label: 'Capital cost (Budget 2026-27; an older DPR said ₹5,177 cr)' },
  overrun:      { v: 0,    lo: 0,    hi: 0.8,  unit: 'share', label: 'Cost overrun (Yettinahole ran +179% over 11 years)' },
  pf_mld:       { v: 500,  lo: 500,  hi: 675,  unit: 'MLD', label: 'Design yield' },
  build_yrs:    { v: 3,    lo: 3,    hi: 6,    unit: 'yr', label: 'Construction period' },
  pf_life_yrs:  { v: 40,   lo: 30,   hi: 50,   unit: 'yr', label: 'Operating life recovered' },
  ramp:         { v: [0.45, 0.65, 0.85, 1], label: 'Utilisation in operating years 1-4 (Stage V drew ~350 of 775 MLD for 18 months)' },
  power_rs_kl:  { v: 12.8, lo: 8.9,  hi: 12.8, unit: '₹/kL', label: 'Power: ₹19.13 cr/month at 500 MLD on grid; ₹13.35 cr with solar' },
  fixed_cr_yr:  { v: 46,   lo: 46,   hi: 46,   unit: '₹ cr/yr', label: 'Staff, repairs, chemicals (₹2.5/kL at design flow, fixed)' },
  insurance:    { v: 0.004, lo: 0.002, hi: 0.009, unit: 'of capex/yr', label: 'Insurance' },
  cpi:          { v: 0.052, lo: 0.045, hi: 0.06, unit: '/yr', label: 'Inflation (RBI FY27 projection)' },
  inr_jpy_dep:  { v: 0.035, lo: 0.015, hi: 0.045, unit: '/yr', label: 'Expected rupee depreciation vs yen (history 0.6-1.4%/yr; interest parity ~4.4%)' },
  tax:          { v: 0.2517, lo: 0.2517, hi: 0.2517, unit: '', label: 'Corporate tax on a private SPV' },
  jica_rate:    { v: 0.012, lo: 0.010, hi: 0.016, unit: 'yen, per yr', label: 'JICA interest rate (Tranche II, water supply)' },
  bond_rate:    { v: 0.09,  lo: 0.085, hi: 0.095, unit: 'nominal', label: 'Municipal or revenue bond coupon' },
  ham_rate:     { v: 0.0875, lo: 0.0875, hi: 0.0875, unit: 'nominal', label: 'HAM annuity interest (bank rate + 3%)' },
  ppp_equity:   { v: 0.15,  lo: 0.14,  hi: 0.16, unit: 'post-tax', label: 'Private equity return target' },
};
const GSEC = 0.074;
const SOCIAL_REAL = 0.04;

// debt = share of the non-grant money; rate = nominal rupee cost; eq_cost = nominal pre-tax return on the rest.
function structures(p) {
  return {
    jica: { name: 'JICA loan via the state', debt: 0.85, rate: p.jica_rate + p.inr_jpy_dep, tenor: 30, grace: 10, eq_cost: GSEC, grant: 0, overrun_on: 'state',
            note: `85% JICA at ${(p.jica_rate * 100).toFixed(1)}% in yen plus ${(p.inr_jpy_dep * 100).toFixed(1)}%/yr expected rupee fall against the yen, carried by Karnataka; 15% state money at its G-sec cost` },
    bond: { name: 'Municipal or revenue bond', debt: 0.80, rate: p.bond_rate, tenor: 15, grace: 2, eq_cost: GSEC, grant: 0, overrun_on: 'state',
            note: '80% bonds at ~9% (10-yr G-sec 7.4% + 100-200 bp; first issue, likely state-guaranteed); 20% BWSSB/state money at G-sec cost' },
    ham:  { name: 'Hybrid annuity (HAM)', debt: 1.0, rate: p.ham_rate, tenor: 18, grace: 0, eq_cost: GSEC, grant: 0.40, overrun_on: 'contractor',
            note: 'Namami Gange model: government pays 40% during construction; the other 60% is paid back as annuities over 15 years from completion at bank rate + 3% (≈8.75%)' },
    ppp:  { name: 'Commercial PPP, ceiling case', debt: 0.70, rate: 0.10, tenor: 18, grace: 3, eq_cost: p.ppp_equity / (1 - p.tax), grant: 0, overrun_on: 'contractor',
            note: '70% bank debt at ~10%; 30% private equity at 15% after tax (≈20% before tax). In practice this would be take-or-pay with a state guarantee' },
  };
}

function defaults() { return Object.fromEntries(Object.entries(PF).map(([k, o]) => [k, o.v])); }

function flows(p) {
  const B = p.build_yrs, N = p.pf_life_yrs, CR = 1e7, KLY = 365000;
  const capex = [], vol = [], opex = [];
  const total = p.capex_cr * (1 + p.overrun);
  for (let y = 0; y < B; y++) capex.push(total * CR / B * Math.pow(1 + p.cpi, y + 0.5));
  for (let k = 1; k <= N; k++) {
    const util = p.ramp[Math.min(k - 1, p.ramp.length - 1)];
    const v = p.pf_mld * util * KLY, idx = Math.pow(1 + p.cpi, B + k - 1);
    vol.push(v);
    opex.push((p.power_rs_kl * v + p.fixed_cr_yr * CR * (p.pf_mld / 500) + p.insurance * total * CR) * idx);
  }
  return { capex, vol, opex };
}

const pv = (arr, off, r) => arr.reduce((a, c, i) => a + c / Math.pow(1 + r, i + off), 0);

function solveTariff(key, p = defaults()) {
  const s = structures(p)[key], B = p.build_yrs, N = p.pf_life_yrs;
  const { capex, vol, opex } = flows(p);
  const wacc = s.debt * s.rate + (1 - s.debt) * s.eq_cost;          // on the non-grant money
  const idxVol = vol.map((v, i) => v * Math.pow(1 + p.cpi, B + i));  // tariff in today's ₹, CPI-indexed
  // 1. Levelised tariff users pay: PV(revenue) = PV(user-funded capex + opex) at the structure's WACC
  const pvVol = pv(idxVol, B, wacc), pvOpex = pv(opex, B, wacc);
  const t_user = ((1 - s.grant) * pv(capex, 0, wacc) + pvOpex) / pvVol;
  const t_opex = pvOpex / pvVol;
  // 2. Full: grant money charged at the state's borrowing cost
  const wF = (1 - s.grant) * wacc + s.grant * GSEC;
  const t_full = (pv(capex, 0, wF) + pv(opex, B, wF)) / pv(idxVol, B, wF);
  // 3. Same project at a single 4% real social discount rate (nominal ≈ 4% + CPI)
  const wS = (1 + SOCIAL_REAL) * (1 + p.cpi) - 1;
  const t_social = (pv(capex, 0, wS) + pv(opex, B, wS)) / pv(idxVol, B, wS);
  // Debt at completion: drawn pro rata, interest capitalised (JICA IDC is in practice paid by the state)
  let debt0 = 0, idc = 0;
  for (let y = 0; y < B; y++) { const dd = s.debt * (1 - s.grant) * capex[y]; const i = debt0 * s.rate + dd * s.rate / 2; idc += i; debt0 += dd + i; }
  const repayYrs = Math.max(1, s.tenor - B);
  const need = s.eq_cost > GSEC ? 1.3 : 1.2;
  // 4. Lender test with sculpted repayment: lowest flat real tariff whose CFADS/DSCR, discounted at the
  //    debt rate over the repayment years, can retire the debt. Bulk sales on take-or-pay (no ramp risk).
  const lender = (years) => {
    const f = flows({ ...p, ramp: [1] });
    let lo = 0, hi = 2000;
    for (let i = 0; i < 60; i++) {
      const t = (lo + hi) / 2;
      let cap = 0;
      for (let k = 1; k <= Math.min(years, N); k++) {
        const cf = t * f.vol[k - 1] * Math.pow(1 + p.cpi, B + k - 1) - f.opex[k - 1];
        cap += cf / need / Math.pow(1 + s.rate, k);
      }
      cap >= debt0 ? hi = t : lo = t;
    }
    return hi;
  };
  return { key, name: s.name, note: s.note, grant: s.grant, overrun_on: s.overrun_on,
           wacc, wacc_real: (1 + wacc) / (1 + p.cpi) - 1,
           t_user, t_full, t_social, t_opex, capital_user: t_user - t_opex,
           t_lender_tenor: lender(repayYrs), t_lender_30: lender(30), repayYrs, dscr_need: need,
           idc_cr: idc / 1e7, debt0_cr: debt0 / 1e7 };
}


